<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;700;900&display=swap" rel="stylesheet">
<style>
  :root{
    --red:#d40920;
    --blue:#1356a2;
    --yellow:#f7d504;
    --ink:#0a0a0a;
    --paper:#ffffff;
    --line:8px;
    --line-thin:4px;
  }
  *{margin:0;padding:0;box-sizing:border-box}
  html{scroll-behavior:smooth}
  body{
    font-family:'Archivo',system-ui,sans-serif;
    background:var(--paper);
    color:var(--ink);
    line-height:1.55;
  }
  h1,h2,h3,.display{font-weight:900;letter-spacing:-0.02em;line-height:1.04;text-transform:uppercase}
  a{color:inherit}
  .wrap{max-width:1120px;margin:0 auto;padding:0 24px}

  /* top bar */
  .topbar{
    border-bottom:var(--line) solid var(--ink);
    display:flex;align-items:center;justify-content:space-between;gap:16px;
    padding:14px 24px;position:sticky;top:0;background:var(--paper);z-index:20;
  }
  .topbar .mark{font-weight:900;text-transform:uppercase;letter-spacing:.08em;font-size:14px;display:flex;gap:8px;align-items:center}
  .swatch{width:14px;height:14px;display:inline-block;border:2px solid var(--ink)}
  .swatch.r{background:var(--red)} .swatch.b{background:var(--blue)} .swatch.y{background:var(--yellow)}
  .topbar nav{display:flex;gap:22px;font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:.08em}
  .topbar nav a{text-decoration:none;border-bottom:3px solid transparent;padding-bottom:2px}
  .topbar nav a:hover{border-bottom-color:var(--red)}
  @media (max-width:720px){ .topbar nav{display:none} }

  /* hero */
  .hero{position:relative;border-bottom:var(--line) solid var(--ink);overflow:hidden}
  #bg{position:absolute;inset:0;width:100%;height:100%;display:block}
  .hero .wrap{
    position:relative;display:grid;grid-template-columns:1.15fr .85fr;gap:48px;align-items:center;
    padding-top:72px;padding-bottom:72px;
  }
  @media (max-width:880px){ .hero .wrap{grid-template-columns:1fr;padding-top:48px;padding-bottom:48px} }
  .kicker{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:22px;font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:.1em}
  .kicker span{border:var(--line-thin) solid var(--ink);padding:5px 10px;background:var(--paper)}
  .kicker span.hot{background:var(--yellow)}
  h1{font-size:clamp(38px,6vw,72px)}
  .lede{margin:22px 0 30px;font-size:clamp(16px,1.6vw,19px);max-width:52ch;font-weight:500}
  .cta-row{display:flex;gap:14px;flex-wrap:wrap;align-items:center}
  .btn{
    display:inline-block;text-decoration:none;font-weight:900;text-transform:uppercase;
    letter-spacing:.06em;font-size:14px;padding:14px 22px;border:var(--line-thin) solid var(--ink);
    background:var(--red);color:#fff;box-shadow:6px 6px 0 var(--ink);transition:transform .12s ease,box-shadow .12s ease;
  }
  .btn:hover{transform:translate(3px,3px);box-shadow:3px 3px 0 var(--ink)}
  .btn.ghost{background:var(--paper);color:var(--ink)}
  .btn.blue{background:var(--blue)}

  /* the painting, rebuilt as a grid */
  .painting{background:var(--ink);display:grid;gap:var(--line);
    grid-template-columns:1.05fr 2.1fr;grid-template-rows:2.35fr 1fr;
    aspect-ratio:1/1;border:var(--line) solid var(--ink);box-shadow:14px 14px 0 rgba(10,10,10,.15);
    max-width:460px;margin-left:auto;width:100%;
  }
  .painting .cell{background:var(--paper)}
  .painting .red{background:var(--red)}
  .painting .blue{background:var(--blue)}
  .painting .yellow{background:var(--yellow)}
